package br.com.sussmartcare.telemetry.application; import br.com.sussmartcare.telemetry.infrastructure.BiometricObservationRepository; import java.util.*; import org.springframework.stereotype.Service; @Service public class TelemetrySummaryService {private final BiometricObservationRepository repo;public TelemetrySummaryService(BiometricObservationRepository r){repo=r;}public Summary summarize(UUID session,String type){var values=repo.findTop50BySessionIdAndTypeOrderByMeasuredAtDesc(session,type).stream().mapToDouble(o->o.getValue()).toArray();if(values.length==0)return new Summary(type,0,null,null,null,"NO_DATA");double min=Arrays.stream(values).min().orElseThrow(),max=Arrays.stream(values).max().orElseThrow(),avg=Arrays.stream(values).average().orElseThrow();String trend=values.length<2?"INSUFFICIENT_DATA":values[0]>values[values.length-1]?"RISING":values[0]<values[values.length-1]?"FALLING":"STABLE";return new Summary(type,values.length,min,max,avg,trend);}public record Summary(String type,int samples,Double min,Double max,Double average,String trend){}}
